template <bool B>
inline bool VerifyPayload(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, Payload type) {
  switch (type) {
    case Payload::NONE: {
      return true;
    }
    case Payload::Enter: {
      auto ptr = reinterpret_cast<const HeavenField::Enter *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::EnterAck: {
      auto ptr = reinterpret_cast<const HeavenField::EnterAck *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::Move: {
      auto ptr = reinterpret_cast<const HeavenField::Move *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::Snapshot: {
      auto ptr = reinterpret_cast<const HeavenField::Snapshot *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::Notice: {
      auto ptr = reinterpret_cast<const HeavenField::Notice *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::Correction: {
      auto ptr = reinterpret_cast<const HeavenField::Correction *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::SetParty: {
      auto ptr = reinterpret_cast<const HeavenField::SetParty *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::PartyState: {
      auto ptr = reinterpret_cast<const HeavenField::PartyState *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::PartnerChanged: {
      auto ptr = reinterpret_cast<const HeavenField::PartnerChanged *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyPayloadVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<Payload> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyPayload(
        verifier,  values->Get(i), types->GetEnum<Payload>(i))) {
      return false;
    }
  }
  return true;
}

